export type ChartCardPoint = {
  label: string;
  value: number;
};

export type ChartCardSeries = {
  id: string;
  label: string;
  points: ChartCardPoint[];
};

export function getChartRange(series: ChartCardSeries[]) {
  const values = series.flatMap((entry) => entry.points.map((point) => point.value));
  const min = values.length > 0 ? Math.min(...values) : 0;
  const max = values.length > 0 ? Math.max(...values) : 0;
  const padding = (max - min) * 0.12;
  return {
    min: Number.isFinite(min) ? min - padding : 0,
    max: Number.isFinite(max) ? max + padding : 1,
  };
}

export function formatChartValue(value: number, options?: Intl.NumberFormatOptions) {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: 1,
    notation: "compact",
    ...options,
  }).format(value);
}

export function toAccessibleSummary(series: ChartCardSeries[]) {
  return series
    .map((entry) => {
      const total = entry.points.reduce((sum, point) => sum + point.value, 0);
      const average = entry.points.length > 0 ? total / entry.points.length : 0;
      return `${entry.label}: ${formatChartValue(average)} average over ${entry.points.length} points`;
    })
    .join("; ");
}

export const chartCardChecks = [
  "Resolve chart data on the server before rendering",
  "Keep the SVG path deterministic for React server rendering",
  "Expose a text summary for assistive technology and no-visual contexts",
] as const;

import { getChartRange, toAccessibleSummary, type ChartCardSeries } from "@/lib/stackfoundry/chart-card";

type ChartCardProps = {
  title: string;
  description?: string;
  series: ChartCardSeries[];
  variant?: "sparkline" | "area";
  footer?: React.ReactNode;
};

function createPath(values: number[], min: number, max: number) {
  const range = max - min || 1;
  return values
    .map((value, index) => {
      const x = (index / Math.max(values.length - 1, 1)) * 100;
      const y = 100 - ((value - min) / range) * 100;
      return `${index === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`;
    })
    .join(" ");
}

export function StackFoundryChartCard({
  title,
  description,
  series,
  variant = "area",
  footer,
}: ChartCardProps) {
  const { min, max } = getChartRange(series);
  const primary = series[0];
  const values = primary?.points.map((point) => point.value) ?? [];
  const linePath = values.length > 1 ? createPath(values, min, max) : undefined;
  const areaPath =
    linePath && variant === "area" ? `${linePath} L100,100 L0,100 Z` : undefined;

  return (
    <section className="overflow-hidden rounded-xl border bg-card shadow-xs">
      <header className="flex flex-col gap-1 border-b p-5">
        <h2 className="text-base font-semibold tracking-tight">{title}</h2>
        {description ? <p className="text-sm text-muted-foreground">{description}</p> : null}
      </header>

      <div className="p-5">
        <figure className="m-0">
          <svg
            className={`h-56 w-full ${variant === "sparkline" ? "opacity-90" : ""}`}
            viewBox="0 0 100 100"
            preserveAspectRatio="none"
            role="img"
            aria-label={`${title}. ${toAccessibleSummary(series)}`}
          >
            <defs>
              <linearGradient id="stackfoundry-chart-fill" x1="0" x2="0" y1="0" y2="1">
                <stop className="stop-color-primary" offset="0" stopOpacity="0.24" />
                <stop className="stop-color-primary" offset="1" stopOpacity="0.02" />
              </linearGradient>
            </defs>
            {areaPath ? <path d={areaPath} fill="url(#stackfoundry-chart-fill)" /> : null}
            {linePath ? (
              <path
                d={linePath}
                className="stroke-primary"
                fill="none"
                strokeWidth={variant === "sparkline" ? 2 : 1.5}
                strokeLinecap="round"
                vectorEffect="non-scaling-stroke"
              />
            ) : null}
          </svg>
          <figcaption className="sr-only">{toAccessibleSummary(series)}</figcaption>
        </figure>

        {series.length > 1 ? (
          <ul className="mt-4 flex flex-wrap gap-x-5 gap-y-2">
            {series.map((entry) => (
              <li className="flex items-center gap-2 text-xs text-muted-foreground" key={entry.id}>
                <span aria-hidden="true" className="h-2 w-2 rounded-full bg-primary" />
                {entry.label}
              </li>
            ))}
          </ul>
        ) : null}
      </div>

      {footer ? <footer className="border-t p-5 text-xs text-muted-foreground">{footer}</footer> : null}
    </section>
  );
}

import { StackFoundryChartCard } from "@/components/stackfoundry/chart-card";

const points = [
  { label: "Monday", value: 8200 },
  { label: "Tuesday", value: 11250 },
  { label: "Wednesday", value: 9840 },
  { label: "Thursday", value: 13480 },
  { label: "Friday", value: 15920 },
  { label: "Saturday", value: 11860 },
  { label: "Sunday", value: 12410 },
];

export default function ChartCardDemo() {
  return (
    <div className="grid gap-5">
      <StackFoundryChartCard
        title="API requests"
        description="Request volume across the last seven days"
        series={[{ id: "requests", label: "Requests", points }]}
        footer="Data refreshes hourly. Values are UTC."
      />
      <StackFoundryChartCard
        title="Active usage"
        description="Compact trend for compact dashboard headers"
        series={[{ id: "usage", label: "Active sessions", points: points.slice(2) }]}
        variant="sparkline"
      />
    </div>
  );
}
